<?= $this->extend('layout') ?><?= $this->section('content') ?><div class="auth panel"><h1>Two-factor verification</h1><p>Enter the current 6-digit code from your authenticator app.</p><form method="post" action="<?= site_url('two-factor/verify') ?>"><?= csrf_field() ?><div class="field"><label>Authenticator code</label><input name="code" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" required></div><button class="btn">Verify</button></form><hr><form method="post" action="<?= site_url('two-factor/recovery') ?>"><?= csrf_field() ?><div class="field"><label>Or use a recovery code</label><input name="recovery_code" required></div><button class="btn gray">Use recovery code</button></form></div><?= $this->endSection() ?>
